def max_absolute_sum(nums):
    n = len(nums)
    best = 0
    for start in range(n):
        total = 0
        for end in range(start, n):
            total += nums[end]                                             # extend the subarray by one and recompute its sum directly
            best = max(best, abs(total))
    return best


if __name__ == "__main__":
    print(max_absolute_sum([1, -3, 2, 3, -4]))

