import java.util.*;

public class Main {
    int maxAbsoluteSum(int[] nums) {
        int n = nums.length;
        int best = 0;
        for (int start = 0; start < n; start++) {
            int total = 0;
            for (int end = start; end < n; end++) {
                total += nums[end];                                              // extend the subarray by one and recompute its sum directly
                best = Math.max(best, Math.abs(total));
            }
        }
        return best;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.maxAbsoluteSum(new int[]{1, -3, 2, 3, -4}));
    }
}

