import java.util.*;

public class Main {
    int maxAbsoluteSum(int[] nums) {
        int maxEnding = 0;                                                        // best (most positive) subarray sum ending here
        int minEnding = 0;                                                        // best (most negative) subarray sum ending here
        int best = 0;
        for (int x : nums) {
            maxEnding = Math.max(x, maxEnding + x);                                 // standard Kadane's, tracking the most positive running sum
            minEnding = Math.min(x, minEnding + x);                                 // mirrored Kadane's, tracking the most negative running sum
            best = Math.max(best, Math.max(maxEnding, -minEnding));
        }
        return best;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.maxAbsoluteSum(new int[]{1, -3, 2, 3, -4}));
    }
}

