    for (int x : nums) {
        maxEnding = max(x, maxEnding + x);                                       // standard Kadane's, tracking the most positive running sum
        minEnding = min(x, minEnding + x);                                       // mirrored Kadane's, tracking the most negative running sum
        best = max({best, maxEnding, -minEnding});
    }
    return best;
}

